CREATE FUNCTION public.fn_log_pedido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ 
BEGIN 
    VALUES (OLD.pedido_id, OLD.status, NEW.status); 
    RETURN NEW; 
END $$;


