-- Name: sp_fechamento_caixa(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_fechamento_caixa()
    LANGUAGE plpgsql
    AS $$ 
BEGIN 
    UPDATE pedidos 
    SET status = 'FATURADO' 
    WHERE status = 'ENTREGUE' 
    AND data_entrega < CURRENT_DATE; 
END; 
$$;


