CREATE MATERIALIZED VIEW public.mv_auditoria_faturamento AS
 SELECT date_trunc('month'::text, p.data_pedido) AS mes,
    sum(((ip.preco_unitario * (ip.quantidade)::numeric) - ip.desconto)) AS total
   FROM (public.itens_pedido ip
     JOIN public.pedidos p ON ((ip.pedido_id = p.pedido_id)))
  GROUP BY (date_trunc('month'::text, p.data_pedido))
  WITH NO DATA;


